    "OwnerSettingsHistoryResponse": {
      "examples": [
        {
          "events": [
            {
              "actor_id": "key-1",
              "actor_type": "api_key",
              "after": {
                "behavior_policy": {
                  "application_confirmation": "on_user_report",
                  "confirm_before": [],
                  "revision": 1
                },
                "preferences": {
                  "boss_search": "allowed"
                },
                "revision": 3
              },
              "before": {
                "behavior_policy": {
                  "application_confirmation": "on_user_report",
                  "confirm_before": [],
                  "revision": 0
                },
                "preferences": {
                  "boss_search": "explicit_request_only"
                },
                "revision": 0
              },
              "changed_at": "2026-09-12T12:00:00Z",
              "changed_fields": [
                "preferences.boss_search"
              ],
              "event_id": 1,
              "policy_revision": 1,
              "revision": 3,
              "user_id": "u1"
            }
          ]
        }
      ],
      "schema": {
        "$defs": {
          "BehaviorPolicyContext": {
            "additionalProperties": false,
            "description": "Versioned rules the runtime can evaluate before a capability executes.",
            "properties": {
              "application_confirmation": {
                "default": "on_user_report",
                "enum": [
                  "always_ask",
                  "on_user_report"
                ],
                "title": "Application Confirmation",
                "type": "string"
              },
              "confirm_before": {
                "default": [],
                "items": {
                  "type": "string"
                },
                "title": "Confirm Before",
                "type": "array"
              },
              "revision": {
                "default": 0,
                "minimum": 0,
                "title": "Revision",
                "type": "integer"
              }
            },
            "title": "BehaviorPolicyContext",
            "type": "object"
          },
          "OwnerSettingsContext": {
            "additionalProperties": false,
            "description": "Owner state, split into model preferences and runtime policy.\n\nThe two sections share one persisted document so a settings screen can\nupdate them atomically, but they do not share semantics. ``preferences`` is\nprojected to the model. ``behavior_policy`` is evaluated by the runtime and\ncarries its own revision, which is sealed into approval records.\n\nOwner-authorized: the authenticated settings endpoint and CLI may update it\ndirectly. The model-facing tool can only create a bound proposal; a system\ninvariant forces that capability through Review, and the sealed change is\napplied only after an owner interaction receipt. Thus conversation or\ndocument wording cannot itself relax the rule that constrains the model.\n\n``revision`` protects the whole settings document from lost updates.\n``behavior_policy.revision`` changes only when an enforceable rule changes,\nso editing a soft display/model preference does not invalidate an unrelated\napproval already waiting for the owner.",
            "properties": {
              "behavior_policy": {
                "$ref": "#/$defs/BehaviorPolicyContext",
                "default": {
                  "application_confirmation": "on_user_report",
                  "confirm_before": [],
                  "revision": 0
                }
              },
              "preferences": {
                "$ref": "#/$defs/UserPreferencesContext",
                "default": {
                  "boss_search": "explicit_request_only"
                }
              },
              "revision": {
                "default": 0,
                "minimum": 0,
                "title": "Revision",
                "type": "integer"
              }
            },
            "title": "OwnerSettingsContext",
            "type": "object"
          },
          "OwnerSettingsEvent": {
            "additionalProperties": false,
            "properties": {
              "actor_id": {
                "title": "Actor Id",
                "type": "string"
              },
              "actor_type": {
                "enum": [
                  "api_key",
                  "cli",
                  "system",
                  "confirmed_agent_proposal"
                ],
                "title": "Actor Type",
                "type": "string"
              },
              "after": {
                "$ref": "#/$defs/OwnerSettingsContext"
              },
              "before": {
                "$ref": "#/$defs/OwnerSettingsContext"
              },
              "changed_at": {
                "format": "date-time",
                "title": "Changed At",
                "type": "string"
              },
              "changed_fields": {
                "items": {
                  "type": "string"
                },
                "title": "Changed Fields",
                "type": "array"
              },
              "event_id": {
                "title": "Event Id",
                "type": "integer"
              },
              "policy_revision": {
                "title": "Policy Revision",
                "type": "integer"
              },
              "revision": {
                "title": "Revision",
                "type": "integer"
              },
              "user_id": {
                "title": "User Id",
                "type": "string"
              }
            },
            "required": [
              "event_id",
              "user_id",
              "revision",
              "policy_revision",
              "actor_type",
              "actor_id",
              "changed_fields",
              "before",
              "after",
              "changed_at"
            ],
            "title": "OwnerSettingsEvent",
            "type": "object"
          },
          "UserPreferencesContext": {
            "additionalProperties": false,
            "description": "Soft owner preferences interpreted by the decision model.\n\nThese are deliberately not described as enforcement.  They depend on the\nmeaning of the current request (for example, whether search was explicitly\nrequested), so the deterministic runtime does not have enough information\nto decide them without inventing a second intent classifier.",
            "properties": {
              "boss_search": {
                "default": "explicit_request_only",
                "enum": [
                  "explicit_request_only",
                  "allowed"
                ],
                "title": "Boss Search",
                "type": "string"
              }
            },
            "title": "UserPreferencesContext",
            "type": "object"
          }
        },
        "additionalProperties": false,
        "properties": {
          "events": {
            "items": {
              "$ref": "#/$defs/OwnerSettingsEvent"
            },
            "title": "Events",
            "type": "array"
          }
        },
        "required": [
          "events"
        ],
        "title": "OwnerSettingsHistoryResponse",
        "type": "object"
      }
    },
