  "requests": {
    "ChatStreamRequest": {
      "examples": [
        {
          "conversation_id": "conv-1",
          "input_resources": [],
          "interaction_response": {
            "action": "confirm",
            "interaction_id": "interaction_0123456789abcdef0123",
            "scope": "capability_confirmation"
          },
          "message": "确认执行"
        },
        {
          "conversation_id": "conv-1",
          "input_resources": [
            {
              "id": "jd-1",
              "kind": "jd_snapshot"
            }
          ],
          "interaction_response": {
            "action": "confirm",
            "interaction_id": "interaction_0123456789abcdef0123",
            "scope": "capability_confirmation"
          },
          "message": "我刚在 BOSS 保存了一个岗位，请继续分析。"
        }
      ],
      "schema": {
        "$defs": {
          "InteractionResponse": {
            "additionalProperties": false,
            "description": "A UI response whose authority is bound to one durable interaction.",
            "properties": {
              "action": {
                "enum": [
                  "confirm",
                  "cancel"
                ],
                "title": "Action",
                "type": "string"
              },
              "interaction_id": {
                "pattern": "^interaction_[a-f0-9]{20}$",
                "title": "Interaction Id",
                "type": "string"
              },
              "scope": {
                "enum": [
                  "resume_analysis_confirmation",
                  "capability_confirmation"
                ],
                "title": "Scope",
                "type": "string"
              }
            },
            "required": [
              "interaction_id",
              "scope",
              "action"
            ],
            "title": "InteractionResponse",
            "type": "object"
          },
          "TurnInputResource": {
            "additionalProperties": false,
            "description": "A durable user asset the message is about, named by id rather than prose.\n\n``resume_version`` is the exact immutable version the user attached;\n``job_posting`` is a saved job the message is about; ``jd_snapshot`` is one\nexact JD version of a saved job, as when the page continues a conversation\nwith the snapshot just captured from a search the agent opened, so the\nconversation stays pinned to that version even after the posting is\ncaptured again. Either way the runtime verifies the id belongs to the\nauthenticated user before any of it reaches the model: the id is never\ntrusted from the message text, and the asset itself never travels in the\nrequest.",
            "properties": {
              "id": {
                "maxLength": 200,
                "minLength": 1,
                "title": "Id",
                "type": "string"
              },
              "kind": {
                "enum": [
                  "resume_version",
                  "job_posting",
                  "jd_snapshot"
                ],
                "title": "Kind",
                "type": "string"
              }
            },
            "required": [
              "kind",
              "id"
            ],
            "title": "TurnInputResource",
            "type": "object"
          }
        },
        "additionalProperties": false,
        "properties": {
          "conversation_id": {
            "maxLength": 200,
            "minLength": 1,
            "title": "Conversation Id",
            "type": "string"
          },
          "input_resources": {
            "default": [],
            "items": {
              "$ref": "#/$defs/TurnInputResource"
            },
            "maxItems": 8,
            "title": "Input Resources",
            "type": "array"
          },
          "interaction_response": {
            "anyOf": [
              {
                "$ref": "#/$defs/InteractionResponse"
              },
              {
                "type": "null"
              }
            ],
            "default": null
          },
          "message": {
            "maxLength": 100000,
            "minLength": 1,
            "title": "Message",
            "type": "string"
          }
        },
        "required": [
          "conversation_id",
          "message"
        ],
        "title": "ChatStreamRequest",
        "type": "object"
      }
    }
  },
